{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine in patients had a mean oral systemic availability of 4.9 ± 3.2%, well below the 20% threshold, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Felodipine absolute oral bioavailability in humans was 15%, below 20%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tegaserod absolute bioavailability was approximately 10% in healthy volunteers, below 20%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug, had mean absolute oral bioavailability of 6.8 ± 3.3% in humans, supporting low F for the similarly lipophilic ester/lactone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain ester prodrug, showed poor and inconsistent oral bioavailability, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat had poor oral bioavailability in humans, supporting low F for a lipophilic, poorly soluble compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nimodipine absolute oral bioavailability was <5% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine absolute bioavailability was 10.7 ± 4.7% after a 20 mg tablet, below 20%, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a lipophilic beta-lactone with a long alkyl chain and N-formyl-leucine ester, designed for local gastrointestinal action and known to be minimally absorbed. All high-transfer experimental analogues—tetrabenazine, felodipine, tegaserod, testosterone undecanoate, dimethandrolone undecanoate, batimastat, nimodipine, and nitrendipine—show absolute oral bioavailability below 20% in humans. The physicochemical prior (high logP, high MW, poor solubility) is consistent. Therefore, F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat itself is included in the supplied evidence; however, the query is identifiable as orlistat, whose systemic absorption is known to be negligible.",
    "Some nitrendipine records report higher F values (30-40%), but these are inconsistent with direct comparative studies and are outweighed by the preponderance of low-F evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

